    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    # The most frequent color is the field; a solid full row/column is the edge marker.
    bg = counts.most_common(1)[0][0]
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            divider = ('h', r)
            break
    if divider is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and next(iter(vals)) != bg:
                divider = ('v', c)
                break
    if divider is None:
        return [row[:] for row in grid]
    border_color = grid[divider[1]][0] if divider[0] == 'h' else grid[0][divider[1]]
    obj_colors = [c for c in counts if c not in (bg, border_color)]
    if not obj_colors:
        return [row[:] for row in grid]
    obj = max(obj_colors, key=lambda c: counts[c])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    out = [row[:] for row in grid]
    if divider[0] == 'v':
        lo, hi = min(c for r,c in pts), max(c for r,c in pts)
        # Draw the line on the side of the object facing the grid's center.
        col = lo - 1 if abs((lo-1) - (w-1)/2) < abs((hi+1) - (w-1)/2) else hi + 1
        if 0 <= col < w:
            for r in range(h): out[r][col] = 8
